export type Status = "confirmed" | "proposed" | "mvp" | "later" | "open";
export type ContentView = "architecture" | "use-cases";

export interface NavigationItem {
  id: string;
  label: string;
  group: ContentView;
}

export interface Actor {
  id: string;
  name: string;
  description: string;
}

export interface UseCase {
  id: string;
  title: string;
  actorIds: string[];
  result: string;
  status: Status;
}

export interface InterfaceUseCase {
  id: string;
  title: string;
  consumers: string[];
  result: string;
  status: Status;
}

export interface FunctionalSystemDefinition {
  code: string;
  name: string;
  responsibility: string;
  sourceOfTruth: string;
  internalDomains: string[];
  useCases: UseCase[];
  interfaceUseCases: InterfaceUseCase[];
  dependsOn: string[];
  subscribes: string[];
  publishes: string[];
  exclusions: string[];
}

export interface EntryApplicationDefinition {
  code: string;
  name: string;
  audience: string;
  purpose: string;
  kind: "human" | "machine" | "infrastructure";
  status: Status;
  capabilities: string[];
  restrictions: string[];
  connectsTo: string[];
}

